#include <stdio.h>
typedef struct Axis6W7Row { unsigned int lane, phase, checkpoint; int delta; } Axis6W7Row;
typedef struct Axis6W7Agg { unsigned int phase[5], checkpoint[5]; int value[5]; } Axis6W7Agg;
static unsigned int mix7(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear7(Axis6W7Agg* a){ for(int i=0;i<5;++i){ a->phase[i]=0u; a->checkpoint[i]=0u; a->value[i]=0; } }
static void absorb7(Axis6W7Agg* a,const Axis6W7Row* r){ unsigned int lane=r->lane%5u; if(r->phase<a->phase[lane]) return; if(r->phase>a->phase[lane]){ a->phase[lane]=r->phase; a->checkpoint[lane]=r->checkpoint; a->value[lane]=r->delta; return; } if(r->checkpoint>a->checkpoint[lane]){ a->checkpoint[lane]=r->checkpoint; a->value[lane]=r->delta; } else if(r->checkpoint==a->checkpoint[lane]) a->value[lane]+=r->delta; }
static unsigned int sig7(const Axis6W7Agg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<5u; ++lane){ h=mix7(h,lane+1u); h=mix7(h,a->phase[lane]); h=mix7(h,a->checkpoint[lane]); h=mix7(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W7Row rows[]={{0u,2u,1u,4},{1u,3u,2u,5},{2u,1u,3u,7},{3u,2u,4u,3},{4u,1u,2u,6},{0u,5u,2u,6},{1u,4u,3u,-1},{2u,5u,2u,8},{3u,4u,5u,2},{4u,5u,3u,4},{0u,5u,2u,-2},{1u,4u,3u,4},{2u,5u,4u,1},{3u,4u,5u,-3},{4u,5u,3u,-1},{0u,6u,4u,5},{1u,6u,5u,3},{2u,6u,4u,6},{3u,6u,6u,1},{4u,6u,2u,2}}; Axis6W7Agg d,r; clear7(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb7(&d,&rows[i]); clear7(&r); for(unsigned int lane=0; lane<5u; ++lane) for(unsigned int phase=1u; phase<=6u; ++phase) for(unsigned int checkpoint=1u; checkpoint<=6u; ++checkpoint){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ unsigned int rotated=(rows[i].lane+2u)%5u; if(rotated!=lane || rows[i].phase!=phase || rows[i].checkpoint!=checkpoint) continue; merged+=rows[i].delta; saw=1; } if(saw){ Axis6W7Row row={(lane+3u)%5u,phase,checkpoint,merged}; absorb7(&r,&row); } } { unsigned int sd=sig7(&d), sr=sig7(&r); printf("%u %u %u\n", sd, sr, (sd==sr)?1u:0u); } return 0; }
